var o=`0181-arancini`;var n=`world-0181`;var a=`IT`;var r=`southern-europe`;var t=4;var l=63;var s={en:`Arancini`,ua:`Аранчині`};var g={en:`A classic dish from Italy, featuring arborio rice, ground beef, yellow onion, mozzarella. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: рис арборіо, яловичий фарш, жовта цибуля, моцарела. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 18 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 18 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:18,i:[[`arborio-rice`,380,`g`],[`vegetable-stock`,850,`ml`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:13,i:[[`ground-beef`,240,`g`],[`yellow-onion`,100,`g`],[`tomato-passata`,170,`g`],[`mozzarella`,160,`g`]]},{en:`Stir the egg and grated Parmesan into cooled cooked rice, then form balls around a spoonful of the cooled meat and mozzarella filling.`,ua:`Вмішайте яйце та натертий пармезан у холодний готовий рис, сформуйте кульки з ложкою охолодженої м’ясної начинки й моцарели всередині.`,t:[`mixing`],m:12,i:[[`chicken-egg`,2,`pcs`],[`parmigiano-reggiano`,85,`g`]]},{en:`Roll the filled rice balls in flour and breadcrumbs, pressing lightly to seal the surface.`,ua:`Обкачайте начинені рисові кульки в борошні та панірувальних сухарях, злегка притискаючи паніровку.`,t:[`standard-breading`],m:9,i:[[`all-purpose-flour`,85,`g`],[`breadcrumbs`,185,`g`]]},{en:`Deep-fry in batches at 175°C until uniformly golden and piping hot in the middle.`,ua:`Обсмажуйте порціями у фритюрі при 175°C до рівномірної золотистості та повного прогрівання всередині.`,t:[`deep-frying`],m:11,i:[[`sunflower-oil`,1e3,`ml`]]}];var u={slug:o,id:n,country:`IT`,region:r,servings:4,minutes:63,title:s,text:g,steps:d};export{a as country,u as default,n as id,l as minutes,r as region,t as servings,o as slug,d as steps,g as text,s as title};